	["Elements"] = [=[--[[
	Elements.lua

	Tab-scoped element constructors: Paragraph, Button, Toggle. Mixed into each Tab object
	returned by Window:Tab (see Window.lua) via __index, so callers write tab:Button{...} etc.

	Paragraph/Button/Toggle/Slider use Helpers.surface - a flat Theme.SurfaceRaised @ 0.3
	transparency background, the same treatment as Window.lua's nav buttons, so tab content reads
	as one family instead of mixing in the separate 9-slice Panel texture (Helpers.panel, still
	used by Window.lua's menu popup and Confirm.lua's dialog, both real extracted values). Toggle
	is a checkmark row (label + a check icon that shows/hides), not an iOS-style knob/track switch
	- the source has no knob/track switch anywhere; every boolean and single-choice setting uses
	this checkmark pattern instead, so this matches the actual source UI rather than inventing one
	that isn't there.
]]

return function(ctx)
	local TweenService = game:GetService("TweenService")
	local UserInputService = game:GetService("UserInputService")

	local Theme = ctx:Require("Theme")
	local Helpers = ctx:Require("Helpers")
	local new, surface, corner = Helpers.new, Helpers.surface, Helpers.corner

	local Elements = {}

	function Elements:_nextOrder()
		self.ElementOrder += 1
		return self.ElementOrder
	end

	function Elements:Paragraph(options)
		options = options or {}

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = options.Title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, 0, 0, 18),
		})

		local descLabel = new("TextLabel", {
			Name = "desc",
			BackgroundTransparency = 1,
			Text = options.Desc or "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Position = UDim2.fromOffset(0, 20),
		})

		local container = surface("Frame", {
			Name = "paragraph",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = self:_nextOrder(),
		}, {
			new("UIPadding", {
				PaddingTop = UDim.new(0, 10),
				PaddingBottom = UDim.new(0, 10),
				PaddingLeft = UDim.new(0, 12),
				PaddingRight = UDim.new(0, 12),
			}),
			titleLabel,
			descLabel,
		})
		container.Parent = self.Page

		local paragraph = {}
		function paragraph:SetTitle(text)
			titleLabel.Text = text
		end
		function paragraph:SetDesc(text)
			descLabel.Text = text
		end
		function paragraph:Destroy()
			container:Destroy()
		end
		return paragraph
	end

	function Elements:Button(options)
		options = options or {}
		local hasIcon = options.Icon ~= nil and options.Icon ~= ""
		local textOffset = hasIcon and 32 or 0

		local icon = new("ImageLabel", Helpers.withIcon({
			Name = "icon",
			BackgroundTransparency = 1,
			Visible = hasIcon,
			ImageColor3 = Theme.Text,
			ImageTransparency = 0.2,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(20, 20),
			Position = UDim2.fromOffset(0, 0),
		}, options.Icon, 48))

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = options.Title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(textOffset, 0),
			Size = UDim2.new(1, -textOffset, 0, 18),
		})

		local descLabel = new("TextLabel", {
			Name = "desc",
			BackgroundTransparency = 1,
			Text = options.Desc or "",
			Visible = options.Desc ~= nil and options.Desc ~= "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Position = UDim2.fromOffset(textOffset, 20),
			Size = UDim2.new(1, -textOffset, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
		})

		local shimmer = new("UIGradient", {
			Enabled = false,
			Transparency = Theme.ShimmerTransparency,
		})

		local button = surface("ImageButton", {
			Name = "button",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = self:_nextOrder(),
		}, {
			shimmer,
			new("UIPadding", {
				PaddingTop = UDim.new(0, 10),
				PaddingBottom = UDim.new(0, 10),
				PaddingLeft = UDim.new(0, 12),
				PaddingRight = UDim.new(0, 12),
			}),
			icon,
			titleLabel,
			descLabel,
		})
		button.Parent = self.Page

		button.MouseEnter:Connect(function()
			TweenService:Create(button, Theme.Tweens.Fast, { BackgroundTransparency = 0.5 }):Play()
		end)
		button.MouseLeave:Connect(function()
			TweenService:Create(button, Theme.Tweens.Fast, { BackgroundTransparency = 0.7 }):Play()
		end)
		Helpers.wireShimmerHover(button, shimmer)
		button.MouseButton1Click:Connect(function()
			if type(options.Callback) == "function" then
				options.Callback()
			end
		end)

		return button
	end

	-- iOS-style track+knob switch, not the checkmark row the real source actually uses anywhere
	-- (it has no knob/track switch at all) - a deliberate, explicitly-requested departure from
	-- 1:1 replication for this one element. Track/knob stay in the same monochrome family as the
	-- rest of the theme (Theme.Surface/SurfaceRaised/Text) rather than introducing an accent hue,
	-- and the knob's slide uses Theme.Tweens.Toggle (Back Out) for the tactile little overshoot
	-- an iOS switch has, instead of the plain eases used everywhere else.
	function Elements:Toggle(options)
		options = options or {}
		local value = options.Value == true
		local hasIcon = options.Icon ~= nil and options.Icon ~= ""
		local textOffset = hasIcon and 32 or 0
		local switchWidth = 44

		local icon = new("ImageLabel", Helpers.withIcon({
			Name = "icon",
			BackgroundTransparency = 1,
			Visible = hasIcon,
			ImageColor3 = Theme.Text,
			ImageTransparency = 0.2,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(20, 20),
			Position = UDim2.fromOffset(0, 0),
		}, options.Icon, 48))

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = options.Title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(textOffset, 0),
			Size = UDim2.new(1, -textOffset - switchWidth - 12, 0, 18),
		})

		local descLabel = new("TextLabel", {
			Name = "desc",
			BackgroundTransparency = 1,
			Text = options.Desc or "",
			Visible = options.Desc ~= nil and options.Desc ~= "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Position = UDim2.fromOffset(textOffset, 20),
			Size = UDim2.new(1, -textOffset - switchWidth - 12, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
		})

		local knob = new("Frame", {
			Name = "knob",
			BackgroundColor3 = Theme.Text,
			BackgroundTransparency = 0.05,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = value and UDim2.fromOffset(32, 12) or UDim2.fromOffset(12, 12),
			Size = UDim2.fromOffset(18, 18),
		}, { corner(Theme.CornerRadiusPill) })

		local switch = new("Frame", {
			Name = "switch",
			BackgroundColor3 = value and Theme.SurfaceRaised or Theme.Surface,
			BackgroundTransparency = value and 0.05 or 0.35,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.fromOffset(switchWidth, 24),
		}, { corner(Theme.CornerRadiusPill), Helpers.stroke(Theme.Glow, 1), knob })

		local hitbox = surface("ImageButton", {
			Name = "toggle",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = self:_nextOrder(),
		}, {
			new("UIPadding", {
				PaddingTop = UDim.new(0, 10),
				PaddingBottom = UDim.new(0, 10),
				PaddingLeft = UDim.new(0, 12),
				PaddingRight = UDim.new(0, 12),
			}),
			icon,
			titleLabel,
			descLabel,
			switch,
		})
		hitbox.Parent = self.Page

		local api = {}

		local function render()
			TweenService:Create(knob, Theme.Tweens.Toggle, {
				Position = value and UDim2.fromOffset(32, 12) or UDim2.fromOffset(12, 12),
			}):Play()
			TweenService:Create(switch, Theme.Tweens.Fast, {
				BackgroundColor3 = value and Theme.SurfaceRaised or Theme.Surface,
				BackgroundTransparency = value and 0.05 or 0.35,
			}):Play()
		end

		-- Deliberately does not invoke options.Callback - this is the programmatic setter (e.g. a
		-- caller resetting a toggle's visual state), not a user click, so it must not re-trigger
		-- whatever the callback does.
		function api:Set(newValue)
			value = newValue == true
			render()
		end

		hitbox.MouseButton1Click:Connect(function()
			value = not value
			render()
			if type(options.Callback) == "function" then
				options.Callback(value)
			end
		end)

		return api
	end

	-- Dashboard-style labeled section: a title+description on the left (real values: 25px
	-- title @ 0.2 transparency, 14px description @ 0.8 transparency, both offset per the
	-- source's own header/description layout) and a horizontal row of icon cards on the
	-- right, added via section:Card{...}. Matches scroll > moderator_tools/server_equipment/
	-- additional_features > features in the source's dashboard_frame.
	function Elements:Section(options)
		options = options or {}

		local descLabel = new("TextLabel", {
			Name = "description",
			BackgroundTransparency = 1,
			Text = options.Desc or "",
			FontFace = Theme.CustomFont,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextTransparency = Theme.SectionDescTransparency,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			TextWrapped = true,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			Position = UDim2.fromOffset(0, 55),
		})

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = options.Title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 25,
			TextColor3 = Theme.Text,
			TextTransparency = Theme.SectionTitleTransparency,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Top,
			TextWrapped = true,
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			Size = UDim2.new(0, 150, 1, 0),
		}, { descLabel })

		local features = new("Frame", {
			Name = "features",
			BackgroundTransparency = 1,
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(1, -180, 1, 0),
		}, {
			new("UIListLayout", {
				FillDirection = Enum.FillDirection.Horizontal,
				Padding = UDim.new(0, 10),
				SortOrder = Enum.SortOrder.LayoutOrder,
			}),
		})

		local container = new("Frame", {
			Name = "section",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 150),
			LayoutOrder = self:_nextOrder(),
		}, {
			new("UIPadding", {
				PaddingTop = UDim.new(0, 20),
				PaddingBottom = UDim.new(0, 20),
				PaddingLeft = UDim.new(0, 20),
			}),
			titleLabel,
			features,
		})
		container.Parent = self.Page

		local section = { Cards = {} }

		local function relayout()
			local count = #section.Cards
			if count == 0 then
				return
			end
			local widthEach = -(10 * (count - 1)) / count
			for _, card in ipairs(section.Cards) do
				card.Size = UDim2.new(1 / count, widthEach, 1, 0)
			end
		end

		function section:Card(cardOptions)
			cardOptions = cardOptions or {}

			local icon = new("ImageLabel", Helpers.withIcon({
				Name = "icon",
				BackgroundTransparency = 1,
				ImageTransparency = Theme.Card.IconTransparency,
				ScaleType = Enum.ScaleType.Fit,
				Size = UDim2.fromOffset(30, 30),
			}, cardOptions.Icon, 48))

			local label = new("TextLabel", {
				Name = "label",
				BackgroundTransparency = 1,
				Text = cardOptions.Title or "",
				FontFace = Theme.CustomFontMedium,
				TextSize = 14,
				TextColor3 = Theme.Text,
				TextTransparency = Theme.Card.LabelTransparency,
				TextWrapped = true,
				AutomaticSize = Enum.AutomaticSize.Y,
				Size = UDim2.new(1, 0, 0, 10),
			})

			local card = new("ImageButton", {
				Name = "card",
				BackgroundColor3 = Theme.Card.Background,
				BackgroundTransparency = Theme.Card.BackgroundTransparency,
				Size = UDim2.new(1, 0, 1, 0),
				LayoutOrder = #section.Cards + 1,
			}, {
				corner(Theme.Card.CornerRadius),
				new("UIListLayout", {
					VerticalAlignment = Enum.VerticalAlignment.Center,
					HorizontalAlignment = Enum.HorizontalAlignment.Center,
					Padding = UDim.new(0, 12),
					SortOrder = Enum.SortOrder.LayoutOrder,
				}),
				new("UIPadding", {
					PaddingTop = UDim.new(0, 10),
					PaddingBottom = UDim.new(0, 10),
					PaddingLeft = UDim.new(0, 15),
					PaddingRight = UDim.new(0, 15),
				}),
				icon,
				label,
			})
			card.Parent = features

			card.MouseEnter:Connect(function()
				TweenService:Create(card, Theme.Tweens.Fast, { BackgroundTransparency = 0.5 }):Play()
			end)
			card.MouseLeave:Connect(function()
				TweenService:Create(card, Theme.Tweens.Fast, { BackgroundTransparency = Theme.Card.BackgroundTransparency }):Play()
			end)
			card.MouseButton1Click:Connect(function()
				if type(cardOptions.Callback) == "function" then
					cardOptions.Callback()
				end
			end)

			table.insert(section.Cards, card)
			relayout()

			return card
		end

		function section:Destroy()
			container:Destroy()
		end

		return section
	end

	-- Real slider values (tools_panels' custom-command rows): pill black@70% track, an inset
	-- "depth" 9-slice shadow image, min/max labels pinned to the ends, and a circular handle
	-- image. The drag math itself is ours, not Krypt's third-party module - see Theme.Slider.
	function Elements:Slider(options)
		options = options or {}
		local min = options.Min or 0
		local max = options.Max or 100
		local increment = options.Increment or 1
		local value = math.clamp(options.Value or min, min, max)

		-- Chip/badge pattern (real "bulked"/"adornee" tag style: BackgroundColor3=TextColor3 @ 0.8
		-- transparency, pill corner, auto-sized) instead of a bare, unpositioned text label.
		local valueLabel = new("TextLabel", {
			Name = "text",
			BackgroundTransparency = 1,
			Text = tostring(value),
			FontFace = Theme.CustomFontMedium,
			TextSize = 12,
			TextColor3 = Theme.Text,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromScale(0, 1),
		})

		local valueBadge = new("Frame", {
			Name = "value",
			BackgroundColor3 = Theme.Text,
			BackgroundTransparency = 0.8,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.fromOffset(0, 20),
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
		}, {
			corner(Theme.CornerRadiusPill),
			new("UIPadding", {
				PaddingLeft = UDim.new(0, 9),
				PaddingRight = UDim.new(0, 9),
			}),
			valueLabel,
		})

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = options.Title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, -50, 0, 20),
		}, { valueBadge })

		local descLabel = new("TextLabel", {
			Name = "desc",
			BackgroundTransparency = 1,
			Text = options.Desc or "",
			Visible = options.Desc ~= nil and options.Desc ~= "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
		})

		local header = new("Frame", {
			Name = "header",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = 1,
		}, {
			new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }),
			titleLabel,
			descLabel,
		})

		local minLabel = new("TextLabel", {
			Name = "min_value",
			BackgroundTransparency = 1,
			Text = tostring(min),
			FontFace = Theme.CustomFont,
			TextSize = 12,
			TextColor3 = Theme.TextMuted,
			Size = UDim2.fromOffset(30, Theme.Slider.TrackHeight),
			Position = UDim2.fromOffset(12, 0),
		})

		local maxLabel = new("TextLabel", {
			Name = "max_value",
			BackgroundTransparency = 1,
			Text = tostring(max),
			FontFace = Theme.CustomFont,
			TextSize = 12,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Right,
			Size = UDim2.fromOffset(30, Theme.Slider.TrackHeight),
			Position = UDim2.new(1, -42, 0, 0),
		})

		local depth = new("ImageLabel", {
			Name = "depth",
			BackgroundTransparency = 1,
			Image = Theme.Slider.DepthImage,
			ImageTransparency = 0.5,
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = Theme.Slider.DepthSliceCenter,
			Size = UDim2.new(1, 0, 1, 0),
		})

		-- Fills the track from the left up to the handle, giving it a sense of progress. Flat
		-- Theme.SurfaceRaised (the same gray used for the nav buttons/panel elements) instead of
		-- the real "focused_bg" blue/purple gradient, which would clash with the rest of the theme.
		local fill = new("Frame", {
			Name = "fill",
			BackgroundColor3 = Theme.SurfaceRaised,
			BorderSizePixel = 0,
			ClipsDescendants = true,
			Size = UDim2.fromScale(0, 1),
			ZIndex = 1,
		}, {
			corner(Theme.CornerRadiusPill),
		})

		-- Real halo pattern (Theme.Icons.Glow) reused here as a soft glow sitting behind the
		-- handle, matching the "lifted" feel of the window controls' own hover halo instead of a
		-- flat plain circle.
		local handleGlow = new("ImageLabel", {
			Name = "glow",
			BackgroundTransparency = 1,
			Image = Theme.Icons.Glow,
			ImageTransparency = 0.5,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(Theme.Slider.HandleSize + 22, Theme.Slider.HandleSize + 22),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 2,
		})

		local handle = new("ImageLabel", {
			Name = "handle",
			BackgroundTransparency = 1,
			Image = Theme.Slider.HandleImage,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(Theme.Slider.HandleSize, Theme.Slider.HandleSize),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0, 0, 0.5, 0),
			ZIndex = 3,
		}, { handleGlow })

		local track = new("TextButton", {
			Name = "track",
			Text = "",
			BackgroundColor3 = Color3.new(0, 0, 0),
			BackgroundTransparency = 0.7,
			Size = UDim2.new(1, 0, 0, Theme.Slider.TrackHeight),
			LayoutOrder = 2,
		}, { corner(Theme.CornerRadiusPill), Helpers.stroke(Theme.Glow, 1), depth, fill, minLabel, maxLabel, handle })

		local container = surface("Frame", {
			Name = "slider",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			LayoutOrder = self:_nextOrder(),
		}, {
			new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10) }),
			new("UIPadding", {
				PaddingTop = UDim.new(0, 10),
				PaddingBottom = UDim.new(0, 10),
				PaddingLeft = UDim.new(0, 12),
				PaddingRight = UDim.new(0, 12),
			}),
			header,
			track,
		})
		container.Parent = self.Page

		local function render()
			local fraction = (value - min) / (max - min)
			TweenService:Create(handle, Theme.Tweens.Fast, {
				Position = UDim2.new(fraction, 0, 0.5, 0),
			}):Play()
			TweenService:Create(fill, Theme.Tweens.Fast, {
				Size = UDim2.fromScale(fraction, 1),
			}):Play()
			valueLabel.Text = tostring(value)
		end

		local function setFromScreenX(x)
			local fraction = math.clamp((x - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
			local raw = min + fraction * (max - min)
			value = math.clamp(math.floor(raw / increment + 0.5) * increment, min, max)
			render()
			if type(options.Callback) == "function" then
				options.Callback(value)
			end
		end

		local dragging = false

		track.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = true
				setFromScreenX(input.Position.X)
			end
		end)

		UserInputService.InputChanged:Connect(function(input)
			if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
				setFromScreenX(input.Position.X)
			end
		end)

		UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				dragging = false
			end
		end)

		render()

		local api = {}

		function api:Set(newValue)
			value = math.clamp(newValue, min, max)
			render()
		end

		function api:Get()
			return value
		end

		return api
	end

	return Elements
end
]=],
	["Notify"] = [=[--[[
	Notify.lua

	Toast notifications. Visual structure (pill-shaped card, white gradient-stroke glow, bottom
	timeline bar that drains over the notification's duration) matches the real values extracted
	from the source project's notification instance: BackgroundColor3 RGB(79,79,79) at ~0.05
	transparency, a white UIStroke with a UIGradient (transparency 0.69-0.87, 80deg rotation), and
	a 100px pill CornerRadius. See HANDOFF.md/Theme.lua for the extraction detail.
]]

return function(ctx)
	local TweenService = game:GetService("TweenService")

	local Theme = ctx:Require("Theme")
	local Helpers = ctx:Require("Helpers")
	local new, corner = Helpers.new, Helpers.corner

	local Notify = {}

	function Notify.Show(window, title, content, icon, duration)
		duration = duration or 5

		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, 0, 0, 16),
		})

		local contentLabel = new("TextLabel", {
			Name = "content",
			BackgroundTransparency = 1,
			Text = content or "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Position = UDim2.fromOffset(0, 18),
		})

		-- Real values: both the track and the fill are the same sliced pill image
		-- (rbxassetid://16294678871, also the slider handle image) rather than flat Color3 pills -
		-- track at 0.8 transparency, fill at 0.2.
		local timelineBar = new("ImageLabel", {
			Name = "bar",
			BackgroundTransparency = 1,
			Image = "rbxassetid://16294678871",
			ImageTransparency = 0.2,
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = Rect.new(206, 206, 206, 206),
			Size = UDim2.fromScale(0, 1),
		})

		local timeline = new("ImageLabel", {
			Name = "timeline",
			BackgroundTransparency = 1,
			Image = "rbxassetid://16294678871",
			ImageTransparency = 0.8,
			ScaleType = Enum.ScaleType.Slice,
			SliceCenter = Rect.new(206, 206, 206, 206),
			Size = UDim2.new(1, -24, 0, 3),
			Position = UDim2.new(0, 12, 1, -8),
		}, { timelineBar })

		-- Real extracted values: white stroke, gradient transparency 0.69->0.87, 80deg rotation -
		-- a subtle, mostly-transparent glow rather than a hard visible ring.
		local strokeGradient = new("UIGradient", {
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.69375),
				NumberSequenceKeypoint.new(1, 0.86875),
			}),
			Rotation = 80,
		})

		local toast = new("Frame", {
			Name = "toast",
			BackgroundColor3 = Theme.SurfaceRaised,
			BackgroundTransparency = 0.05,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			Position = UDim2.new(0.5, 0, 0, -80),
			AnchorPoint = Vector2.new(0.5, 0),
			ClipsDescendants = true,
		}, {
			corner(Theme.CornerRadiusPill),
			Helpers.stroke(Theme.Glow, 1),
			strokeGradient,
			new("UIPadding", {
				PaddingTop = UDim.new(0, 12),
				PaddingBottom = UDim.new(0, 16),
				PaddingLeft = UDim.new(0, 16),
				PaddingRight = UDim.new(0, 16),
			}),
			titleLabel,
			contentLabel,
			timeline,
		})

		if not window.NotifyContainer then
			window.NotifyContainer = new("Frame", {
				Name = "notifications",
				BackgroundTransparency = 1,
				Size = UDim2.new(0, 320, 1, 0),
				Position = UDim2.new(1, -336, 0, 16),
			}, {
				new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }),
			})
			window.NotifyContainer.Parent = window.ScreenGui
		end
		toast.Parent = window.NotifyContainer

		TweenService:Create(toast, Theme.Tweens.Window, { Position = UDim2.new(0.5, 0, 0, 0) }):Play()
		TweenService:Create(timelineBar, TweenInfo.new(duration, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(1, 1) }):Play()

		local dismissed = false
		local function dismiss()
			if dismissed then
				return
			end
			dismissed = true
			TweenService:Create(toast, Theme.Tweens.Window, { Position = UDim2.new(0.5, 0, 0, -80) }):Play()
			task.wait(0.4)
			toast:Destroy()
		end

		toast.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 then
				dismiss()
			end
		end)

		task.delay(duration, dismiss)
	end

	return Notify
end
]=],
	["Confirm"] = [=[--[[
	Confirm.lua

	Confirm/cancel modal. Interaction pattern (confirm/cancel buttons, background-click-to-cancel,
	hover/press color feedback) adapted from the source project's prompt_handler.luau, which was
	already fully generic. Dialog uses the real 9-slice panel texture (Helpers.panel) with the
	real pop-in animation (ImageTransparency 1->0.1, UIScale 1.2->1) the source uses for every
	panel open.

	Layout is a UIListLayout (title/content/buttons stacked, dialog AutomaticSize=Y) rather than
	fixed offsets - the original had a hardcoded 128px dialog height with the button row pinned
	at a fixed y=70, which worked for short test strings but overlapped/clipped for anything
	longer once content actually wrapped to 3+ lines. Buttons also now get the same rotating-
	shimmer hover (Helpers.wireShimmerHover) and Theme.Surface/SurfaceRaised coloring as every
	other interactive element in the library, instead of the old hardcoded RGB(85,89,91)/
	RGB(100,105,107) one-off colors with no shimmer at all.
]]

return function(ctx)
	local TweenService = game:GetService("TweenService")

	local Theme = ctx:Require("Theme")
	local Helpers = ctx:Require("Helpers")
	local BulkFade = ctx:Require("BulkFade")
	local new, panel, corner = Helpers.new, Helpers.panel, Helpers.corner

	local Confirm = {}

	function Confirm.Show(window, title, content, callback)
		local titleLabel = new("TextLabel", {
			Name = "title",
			BackgroundTransparency = 1,
			Text = title or "",
			FontFace = Theme.CustomFontMedium,
			TextSize = 18,
			TextColor3 = Theme.Text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			LayoutOrder = 1,
		})

		local contentLabel = new("TextLabel", {
			Name = "content",
			BackgroundTransparency = 1,
			Text = content or "",
			FontFace = Theme.CustomFont,
			TextSize = 14,
			TextColor3 = Theme.Text,
			TextTransparency = 0.2,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextWrapped = true,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(1, 0, 0, 0),
			LayoutOrder = 2,
		})

		local cancelShimmer = new("UIGradient", { Enabled = false, Transparency = Theme.ShimmerTransparency })
		local cancelButton = new("TextButton", {
			Name = "cancel",
			Text = "Cancel",
			FontFace = Theme.CustomFontMedium,
			TextSize = 17,
			TextColor3 = Theme.Text,
			TextTransparency = 0.2,
			BackgroundColor3 = Theme.Surface,
			BackgroundTransparency = 0.4,
			Size = UDim2.new(0.4, -5, 0, 45),
		}, { corner(Theme.CornerRadiusPill), cancelShimmer })

		local confirmShimmer = new("UIGradient", { Enabled = false, Transparency = Theme.ShimmerTransparency })
		local confirmButton = new("TextButton", {
			Name = "confirm",
			Text = "Continue",
			FontFace = Theme.CustomFontSemiBold,
			TextSize = 17,
			TextColor3 = Theme.Text,
			BackgroundColor3 = Theme.SurfaceRaised,
			BackgroundTransparency = 0.05,
			Size = UDim2.new(0.6, -5, 0, 45),
		}, { corner(Theme.CornerRadiusPill), confirmShimmer })

		local buttonRow = new("Frame", {
			Name = "buttons",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, 45),
			LayoutOrder = 3,
		}, {
			new("UIListLayout", {
				FillDirection = Enum.FillDirection.Horizontal,
				Padding = UDim.new(0, 10),
				SortOrder = Enum.SortOrder.LayoutOrder,
			}),
			cancelButton,
			confirmButton,
		})

		local dialogScale = new("UIScale", { Scale = 1.2 })
		local dialog = panel("ImageLabel", {
			Name = "dialog",
			ImageTransparency = 1,
			AutomaticSize = Enum.AutomaticSize.Y,
			Size = UDim2.new(0, 380, 0, 0),
			Position = UDim2.fromScale(0.5, 0.5),
			AnchorPoint = Vector2.new(0.5, 0.5),
		}, {
			dialogScale,
			new("UIListLayout", { Padding = UDim.new(0, 14), SortOrder = Enum.SortOrder.LayoutOrder }),
			new("UIPadding", {
				PaddingTop = UDim.new(0, 18),
				PaddingBottom = UDim.new(0, 18),
				PaddingLeft = UDim.new(0, 18),
				PaddingRight = UDim.new(0, 18),
			}),
			titleLabel,
			contentLabel,
			buttonRow,
		})

		local overlay = new("TextButton", {
			Name = "confirm_overlay",
			Text = "",
			BackgroundColor3 = Color3.new(0, 0, 0),
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
		}, { dialog })
		overlay.Parent = window.ScreenGui

		-- Fades title/content/buttons together with the panel itself, instead of just the panel's
		-- own ImageTransparency tweening while everything on top of it pops in/out already-opaque.
		-- Built fresh every Show() call (each dialog is a one-shot instance, never reused), so
		-- there's no risk of BulkFade's "captures values once, forever" snapshot going stale the
		-- way it could for the main Window's long-lived, repeatedly-toggled content.
		local descendants = dialog:GetDescendants()
		local openFade = BulkFade.CreateGroup(descendants, Theme.Tweens.PanelOpen)
		local openSnap = BulkFade.CreateGroup(descendants, TweenInfo.new(0))
		local closeFade = BulkFade.CreateGroup(descendants, Theme.Tweens.PanelClose)

		openSnap:FadeOut()
		TweenService:Create(overlay, Theme.Tweens.PanelOpen, { BackgroundTransparency = 0.5 }):Play()
		TweenService:Create(dialog, Theme.Tweens.PanelOpen, { ImageTransparency = 0.1 }):Play()
		TweenService:Create(dialogScale, Theme.Tweens.PanelOpen, { Scale = 1 }):Play()
		openFade:FadeIn()

		local function close()
			TweenService:Create(overlay, Theme.Tweens.PanelClose, { BackgroundTransparency = 1 }):Play()
			TweenService:Create(dialog, Theme.Tweens.PanelClose, { ImageTransparency = 1 }):Play()
			TweenService:Create(dialogScale, Theme.Tweens.PanelClose, { Scale = 1.2 }):Play()
			closeFade:FadeOut()
			task.delay(Theme.Tweens.PanelClose.Time, function()
				overlay:Destroy()
			end)
		end

		local function hoverColor(button, transparency, hoverTransparency)
			button.MouseEnter:Connect(function()
				TweenService:Create(button, Theme.Tweens.Fast, { BackgroundTransparency = hoverTransparency }):Play()
			end)
			button.MouseLeave:Connect(function()
				TweenService:Create(button, Theme.Tweens.Fast, { BackgroundTransparency = transparency }):Play()
			end)
		end

		hoverColor(cancelButton, 0.4, 0.2)
		hoverColor(confirmButton, 0.05, 0)
		Helpers.wireShimmerHover(cancelButton, cancelShimmer)
		Helpers.wireShimmerHover(confirmButton, confirmShimmer)

		cancelButton.MouseButton1Click:Connect(close)
		overlay.MouseButton1Click:Connect(close)
		confirmButton.MouseButton1Click:Connect(function()
			close()
			if type(callback) == "function" then
				callback()
			end
		end)
	end

	return Confirm
end
]=],
	["Window"] = [=[--[[
	Window.lua

	Window creation and chrome, rebuilt to match the source project's real navigation model
	instead of inventing a Rayfield-style sidebar. The source has no persistent sidebar at all:
	- window_handler.luau: a small drag "handle" button (real icon rbxassetid://12974354535) that
	  both drags the window and toggles a "controls" cluster (resize + fullscreen/restore icons,
	  the halo-hover pattern already in Helpers.wireIconHover).
	- exe_main_module.luau (:Go_To): pages are CanvasGroups switched by tweening Position
	  ((.5,0,1,0) visible / (.5,0,1.2,0) off-screen below) and GroupTransparency together, on the
	  real "slow" (.8s Exponential) tween - not UIPageLayout.
	- menu_handler.luau / navigation_buttons: a small circular nav button (real icon
	  rbxassetid://11295285432) opens a floating popup menu (menu_frame) listing the available
	  pages; picking one calls Go_To and closes the popup. This popup - not a sidebar - is how
	  navigation actually works in the source.
	- exe_main_module:exe_admin_panel: opening/closing the whole window tweens BackgroundTransparency
	  and a UIScale from 1.2->1, on the real "info" (.8s Exponential Out) tween - not an instant
	  Enabled flip. (The real source also drives a Lighting BlurEffect here; left out of LumenUI
	  by request.)
]]

return function(ctx)
	local TweenService = game:GetService("TweenService")
	local UserInputService = game:GetService("UserInputService")

	local Theme = ctx:Require("Theme")
	local Helpers = ctx:Require("Helpers")
	local BulkFade = ctx:Require("BulkFade")
	local new, corner, stroke, panel, setOwnCorner, safeUiParent =
		Helpers.new, Helpers.corner, Helpers.stroke, Helpers.panel, Helpers.setOwnCorner, Helpers.safeUiParent

	local Window = {}
	Window.__index = Window

	local MIN_SIZE = Vector2.new(550, 350)

	-- Flattens a list of root instances into itself + every descendant, so a BulkFade group
	-- covers a whole chrome cluster (icons, gradients, nested frames) from just its top-level
	-- parts. `opaque` roots are included themselves but not walked into - see pagesContainer's
	-- use of this, which owns its own fade (a CanvasGroup) precisely so its contents are never
	-- captured here.
	local function withDescendants(roots, opaque)
		opaque = opaque or {}
		local result = {}
		for _, root in ipairs(roots) do
			table.insert(result, root)
			if not opaque[root] then
				for _, descendant in ipairs(root:GetDescendants()) do
					table.insert(result, descendant)
				end
			end
		end
		return result
	end

	-- BulkFade.CreateGroup snapshots each element's transparency at call time and treats that as
	-- the "appear" target forever after - so if it's rebuilt AFTER a fade-out (elements already
	-- sitting at 1), the new snapshot just captures 1 and FadeIn becomes a no-op (1 -> 1). The fix
	-- is to snapshot the real authored values exactly once, the first time a panel's shown, and
	-- keep reusing that same pair of groups (a same-snapshot 0-time "snap" group for the instant
	-- reset, and a real-tween "fade" group for the animated move) for every later toggle.
	local function buildFadePair(elements, tween)
		return BulkFade.CreateGroup(elements, tween), BulkFade.CreateGroup(elements, TweenInfo.new(0))
	end

	-- Real window_controls.controls.restore/resize structure: icon + halo "selection" image,
	-- each with its own UIScale, driven by Helpers.wireIconHover.
	local function controlButton(props)
		local iconScale = new("UIScale", { Scale = 1 })
		local icon = new("ImageLabel", {
			Name = "icon",
			BackgroundTransparency = 1,
			Image = props.Icon,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(20, 20),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 2,
		}, { iconScale })

		local selectionScale = new("UIScale", { Scale = 0.5 })
		local selection = new("ImageLabel", {
			Name = "selection",
			BackgroundTransparency = 1,
			Image = Theme.Icons.Glow,
			ImageTransparency = 1,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(40, 40),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 1,
		}, { selectionScale })

		local button = new("ImageButton", {
			Name = props.Name,
			BackgroundTransparency = 1,
			Size = UDim2.fromOffset(50, 50),
			LayoutOrder = props.LayoutOrder,
		}, { selection, icon })

		Helpers.wireIconHover(button, iconScale, selection, selectionScale)

		return button, icon
	end

	-- Real navigation_buttons pattern: a pill-shaped, near-transparent white button with a
	-- centered icon, using the rotating-shimmer hover (Helpers.wireShimmerHover) instead of the
	-- halo pattern - this is the source's OTHER hover style, used for nav/action icon buttons.
	local function navButton(props)
		local iconScale = new("UIScale", { Scale = 1 })
		-- Falls back to the hamburger glyph both when no icon was requested (props.Icon is nil)
		-- and when one was requested but the name isn't a real Lucide icon - Helpers.icon can't
		-- tell those two apart on its own, so the fallback has to be supplied here.
		local icon = new("ImageLabel", Helpers.withIcon({
			Name = "icon",
			BackgroundTransparency = 1,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromScale(0.45, 0.45),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
		}, props.Icon, 48, Theme.Icons.Menu), { iconScale })

		local shimmer = new("UIGradient", {
			Enabled = false,
			Transparency = Theme.ShimmerTransparency,
		})

		local button = new("ImageButton", {
			Name = props.Name or "nav",
			BackgroundColor3 = Theme.SurfaceRaised,
			BackgroundTransparency = 0.3,
			Size = props.Size or UDim2.fromOffset(40, 40),
			Position = props.Position,
			AnchorPoint = props.AnchorPoint,
			LayoutOrder = props.LayoutOrder,
		}, { corner(Theme.CornerRadiusPill), shimmer, icon })

		Helpers.wireShimmerHover(button, shimmer)

		button.MouseEnter:Connect(function()
			TweenService:Create(iconScale, Theme.Tweens.Fast, { Scale = 1.2 }):Play()
		end)
		button.MouseButton1Down:Connect(function()
			TweenService:Create(iconScale, Theme.Tweens.Fast, { Scale = 0.8 }):Play()
		end)
		button.InputEnded:Connect(function()
			TweenService:Create(iconScale, Theme.Tweens.Fast, { Scale = 1 }):Play()
		end)

		return button
	end

	function Window.new(options)
		options = options or {}

		local screenGui = new("ScreenGui", {
			Name = options.Name or "LumenUI",
			ResetOnSpawn = false,
			ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
			DisplayOrder = 100,
			Parent = safeUiParent(),
		})

		local viewport = workspace.CurrentCamera.ViewportSize
		local maxSize = Vector2.new(viewport.X - 50, viewport.Y - 50)
		local initialSize = options.Size or UDim2.fromOffset(620, 470)

		local titleLabel = new("TextLabel", {
			Name = "title",
			Visible = false,
			BackgroundTransparency = 1,
			Text = options.Title or "LumenUI",
			FontFace = Theme.CustomFontMedium,
			TextSize = 18,
			TextColor3 = Theme.Text,
			TextTransparency = 0.2,
			Size = UDim2.new(1, -32, 0, 24),
			Position = UDim2.fromOffset(16, 44),
		})

		-- Small muted breadcrumb under the window title showing which tab is active - kept in
		-- sync by GoTo(), the only place a tab ever becomes active.
		local tabLabel = new("TextLabel", {
			Name = "tab_label",
			Visible = false,
			BackgroundTransparency = 1,
			Text = "",
			FontFace = Theme.CustomFont,
			TextSize = 13,
			TextColor3 = Theme.TextMuted,
			TextXAlignment = Enum.TextXAlignment.Left,
			Size = UDim2.new(1, -32, 0, 16),
			Position = UDim2.fromOffset(16, 70),
		})

		-- Rayfield-style intro: a small "Welcome back" card shown instead of popping the full
		-- window straight in - see Window:_playIntro, called at the bottom of Window.new.
		local splashWelcome = new("TextLabel", {
