		local splashLayer = new("Frame", {
			Name = "splash",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			ZIndex = 30,
		}, { splashWelcome, splashHubName })

		local handleIcon = new("ImageLabel", {
			Name = "icon",
			BackgroundTransparency = 1,
			Image = Theme.Icons.Handle,
