		local handle = new("ImageButton", {
			Name = "handle",
			Visible = false,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			ZIndex = 10,
			Size = UDim2.fromOffset(60, 40),
			Position = UDim2.new(0.5, 0, 0, 0),
